#!/usr/bin/env python3
"""Stretch-goal tables (CSV, .tex) and the moderator chart from stretch.csv. No new estimation.
Usage: python3 code/python/04e3_stretch_tables.py --date YYYY-MM-DD"""
import argparse, os, sys
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
ap = argparse.ArgumentParser(); ap.add_argument("--date", required=True); a = ap.parse_args()
R = f"results/{a.date}/stretch"; F = f"results/{a.date}/figures"; src = f"{R}/stretch.csv"
if not os.path.exists(src): sys.exit(f"Missing input: {src}")
r = pd.read_csv(src); os.makedirs(F, exist_ok=True)
def stars(p): return "" if pd.isna(p) else "***" if p < .01 else "**" if p < .05 else "*" if p < .1 else ""
def cell(x, d=4): return f"{x.estimate:.{d}f}{stars(x.pval)} ({x.se:.{d}f})"
def tex(df, path):
    t = ["% Generated by code/python/04e3_stretch_tables.py. Do not edit by hand.", "\\begin{tabular}{l" + "r" * (len(df.columns) - 1) + "}", "\\toprule", " & ".join(c.replace("_", "\\_").replace("&", "\\&") for c in df.columns) + " \\\\", "\\midrule"]
    t += [" & ".join(str(v).replace("_", "\\_").replace("&", "\\&") for v in x.values) + " \\\\" for _, x in df.iterrows()] + ["\\bottomrule", "\\end{tabular}"]; open(path, "w").write("\n".join(t) + "\n")
iv = r[(r.block == "iv") & (r.spec == "base2015")]; Y = ["ln_ec", "ln_ee", "renew_share", "new_renew_mw"]
g = lambda y, t: iv[(iv.outcome == y) & (iv.term == t)].iloc[0]
s = pd.DataFrame([{"Outcome": y, "OLS": cell(g(y, "ols_same_sample"), 2 if y == "new_renew_mw" else 4), "Reduced form": cell(g(y, "reduced_form"), 2 if y == "new_renew_mw" else 4), "IV (uninformative)": cell(g(y, "iv_second_stage"), 2 if y == "new_renew_mw" else 4)} for y in Y])
s.to_csv(f"{R}/iv_table.csv", index=False); tex(s, f"{R}/iv_table.tex")
fs = pd.DataFrame([{"Base year": ("2015" if sp == "base2015" else "2014 (check)"), "First-stage coefficient": cell(x), "KP F": f"{k.estimate:.2f}", "KP rank LM": f"{l.estimate:.2f}", "Rank p": f"{l.pval:.3f}", "N": int(x.N)} for sp in ("base2015", "base2014") for x, k, l in [tuple(r[(r.spec == sp) & (r.term == t)].iloc[0] for t in ("Z_on_AI", "KP_F", "KP_rank_LM"))]])
fs.to_csv(f"{R}/iv_first_stage.csv", index=False); tex(fs, f"{R}/iv_first_stage.tex")
m = r[r.block == "mod"]; rows = []
for sp, lab in (("broadband", "Broadband, 2016-2024, no 2020"), ("rdshare", "R&D share of GDP, 2017-2023")):
    for y in Y:
        d = m[(m.spec == sp) & (m.outcome == y)].set_index("term"); dp = 2 if y == "new_renew_mw" else 4; c = lambda t: cell(d.loc[t], dp)
        rows.append({"Moderator": lab, "Outcome": y, "AI x moderator": c("interaction"), "Moderator main effect": c("main_effect"), "AI slope at p25": c("AI_slope_p25"), "AI slope at p75": c("AI_slope_p75"), "N": int(d.loc["interaction", "N"])})
t = pd.DataFrame(rows); t.to_csv(f"{R}/moderation_table.csv", index=False); tex(t, f"{R}/moderation_table.tex")
BLUE, OR, INK, MUTE, GRID, SURF = "#2a78d6", "#eb6834", "#0b0b0b", "#52514e", "#e4e3df", "#fcfcfb"
plt.rcParams.update({"font.family": "DejaVu Sans", "font.size": 10, "axes.edgecolor": GRID, "text.color": INK, "axes.labelcolor": MUTE, "xtick.color": MUTE, "ytick.color": INK})
fig, ax = plt.subplots(1, 4, figsize=(13, 3.6), facecolor=SURF)
for A, y in zip(ax, Y):
    A.set_facecolor(SURF); A.axvline(0, color=MUTE, lw=1)
    for i, (sp, lab) in enumerate((("broadband", "Broadband"), ("rdshare", "R&D share"))):
        for j, (tm, c, nm) in enumerate((("AI_slope_p25", BLUE, "25th percentile"), ("AI_slope_p75", OR, "75th percentile"))):
            x = m[(m.spec == sp) & (m.outcome == y) & (m.term == tm)].iloc[0]; yy = 1 - i + (.14 if j == 0 else -.14)
            A.plot([x.ci_lo, x.ci_hi], [yy, yy], color=c, lw=2, solid_capstyle="round"); A.plot([x.estimate], [yy], "o", ms=7, mec=c, mew=2, mfc=c if x.pval < .05 else SURF, label=nm if i == 0 else None)
    A.set_title(y, loc="left", fontsize=10); A.set_yticks([1, 0]); A.set_yticklabels(["Broadband", "R&D share"] if A is ax[0] else ["", ""]); A.set_ylim(-.5, 1.5); A.grid(axis="x", color=GRID, lw=.8); A.locator_params(axis="x", nbins=4); A.tick_params(axis="y", length=0)
    for s_ in ("top", "right", "left"): A.spines[s_].set_visible(False)
h, l = ax[0].get_legend_handles_labels(); fig.legend(h, l, title="Moderator at its", loc="lower right", ncol=2, frameon=False, fontsize=9)
fig.suptitle("AI slope at low and high values of each moderator, with 95% CIs", x=.012, y=.98, ha="left", fontsize=12.5, fontweight="bold"); fig.tight_layout(rect=(0, .1, 1, .92))
fig.savefig(f"{F}/04e_stretch_moderation.png", dpi=180, facecolor=SURF)
print(fs.to_string(index=False)); print(s.to_string(index=False))
